int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> L(N);
    for (int i = 0; i < N; i++) {
        cin >> L[i];
    }

    int i = 0, j = N - 1;
    long long ops = 0;

    while (i < j) {
        if (L[i] == L[j]) {
            i++;
            j--;
        } else if (L[i] < L[j]) {
            L[i + 1] += L[i];
            i++;
            ops++;
        } else {
            L[j - 1] += L[j];
            j--;
            ops++;
        }
    }

    cout << ops << '\n';
    return 0;
}
